// Автопрохождение копии DISC-теста в headless Chrome
const puppeteer = require('puppeteer-core');
const fs = require('fs');

const sleep = (ms) => new Promise(r => setTimeout(r, ms));

(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/google-chrome',
    headless: 'new',
    args: ['--no-sandbox', '--disable-gpu', '--window-size=1400,1000'],
    defaultViewport: { width: 1400, height: 1000 }
  });
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  // перехват любых сетевых запросов (должно быть пусто)
  const netRequests = [];
  page.on('request', r => { if (!r.url().startsWith('file://') && !r.url().startsWith('data:')) netRequests.push(r.url()); });

  await page.goto('file:///tmp/discbuild/index.html', { waitUntil: 'load' });

  // --- старт ---
  await page.screenshot({ path: 'shot-start.png' });
  await page.click('[data-disc-open]');
  await sleep(300);
  const modalOpen = await page.$eval('#wizardmodal', el => el.classList.contains('is-open'));
  const panes = await page.$$eval('.disc-pane', els => els.length);
  const lists = await page.$$eval('.disc-list', els => els.length);
  const items = await page.$$eval('.disc-item', els => els.length);
  console.log(JSON.stringify({ modalOpen, panes, lists, items }));
  await page.screenshot({ path: 'shot-step1.png' });

  // --- вычисляем ожидаемый счёт: во всех карточках переносим верхний (pos0) вниз ---
  const expected = await page.evaluate(() => {
    const maj = [], min = [];
    document.querySelectorAll('.disc-list').forEach(ul => {
      const types = [...ul.querySelectorAll('.disc-item')].map(li => li.getAttribute('data-type'));
      // после переноса t0 вниз: порядок t1,t2,t3,t0 -> maj = t1, min = t0
      maj.push(types[1]); min.push(types[0]);
    });
    const cnt = (a, ch) => a.reduce((s, v) => s + (v === ch ? 1 : 0), 0);
    const r = {};
    for (const t of ['d','i','s','c']) r[t] = cnt(maj, t) - cnt(min, t);
    return r;
  });

  // --- 8 шагов: на каждом шаге таскаем первый элемент каждой карточки в конец ---
  const dragFirstToLast = async () => {
    const rects = await page.evaluate(() => {
      const active = document.querySelector('.disc-pane.is-active');
      return [...active.querySelectorAll('.disc-list')].map(ul => {
        const items = [...ul.querySelectorAll('.disc-item')];
        const r0 = items[0].getBoundingClientRect();
        const rL = items[items.length - 1].getBoundingClientRect();
        return { from: { x: r0.x + r0.width / 2, y: r0.y + r0.height / 2 }, to: { x: rL.x + rL.width / 2, y: rL.y + rL.height / 2 } };
      });
    });
    for (const r of rects) {
      await page.mouse.move(r.from.x, r.from.y);
      await sleep(60);
      await page.mouse.down();
      await sleep(60);
      // плавное движение вниз
      const steps = 12;
      for (let s = 1; s <= steps; s++) {
        await page.mouse.move(
          r.from.x,
          r.from.y + (r.to.y - r.from.y) * s / steps,
          { steps: 1 }
        );
        await sleep(20);
      }
      // дотягиваем чуть ниже середины последнего элемента, чтобы встать после него
      await page.mouse.move(r.to.x, r.to.y + 20, { steps: 3 });
      await sleep(60);
      await page.mouse.up();
      await sleep(120);
    }
  };

  for (let step = 0; step < 8; step++) {
    await dragFirstToLast();
    // проверяем порядок первого списка шага
    const order = await page.evaluate(() => {
      const active = document.querySelector('.disc-pane.is-active');
      return [...active.querySelectorAll('.disc-list')].map(ul =>
        [...ul.querySelectorAll('.disc-item')].map(li => li.getAttribute('data-type')).join('')
      );
    });
    // проверяем прогресс
    const pct = await page.$eval('#discProgress', el => el.style.width);
    console.log(JSON.stringify({ step: step + 1, order, progress: pct }));
    if (step < 7) {
      await page.click('[data-disc-next]');
      await sleep(200);
    }
    if (step === 3) await page.screenshot({ path: 'shot-step4.png' });
  }
  await page.screenshot({ path: 'shot-step8.png' });

  // --- завершение ---
  await page.click('[data-disc-finish]');
  await sleep(300);
  const resultVisible = await page.$eval('#discResult', el => el.classList.contains('is-active'));
  const line = await page.$eval('#discScoreLine', el => el.textContent);
  const tiles = await page.$$eval('.score-tile__value', els => els.map(e => e.textContent));
  console.log(JSON.stringify({ resultVisible, line, tiles, expected }));
  await page.screenshot({ path: 'shot-result.png' });

  // --- рестарт ---
  await page.click('#discRestart');
  await sleep(300);
  const after = await page.evaluate(() => {
    const ul = document.querySelector('.disc-list');
    return [...ul.querySelectorAll('.disc-item')].map(li => li.getAttribute('data-type')).join('');
  });
  const step0again = await page.$eval('.disc-pane.is-active', el => el.dataset.stepPane);
  console.log(JSON.stringify({ afterRestartFirstList: after, activePane: step0again }));

  // --- Esc закрывает, повторное открытие сохраняет шаг ---
  await page.keyboard.press('Escape');
  await sleep(200);
  const closed = await page.$eval('#wizardmodal', el => !el.classList.contains('is-open'));
  await page.click('.hero__cta [data-disc-open]');
  await sleep(200);
  const reopenedPane = await page.$eval('.disc-pane.is-active', el => el.dataset.stepPane);
  const scrollUnlocked = await page.evaluate(() => !document.documentElement.classList.contains('no-scroll'));
  console.log(JSON.stringify({ escClosed: closed, reopenedPane, scrollUnlocked }));

  // клавиатурная навигация по табам (клик по 5-му табу)
  await page.evaluate(() => document.querySelectorAll('[data-step-btn]')[4].click());
  await sleep(150);
  const tab5 = await page.$eval('.disc-pane.is-active', el => el.dataset.stepPane);
  const prevDisabled = await page.$eval('[data-disc-prev]', el => el.disabled);
  console.log(JSON.stringify({ tabJump: tab5, prevDisabledOnStep0: prevDisabled }));

  console.log(JSON.stringify({ jsErrors: errors, externalRequests: netRequests }));
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

