const puppeteer = require('puppeteer-core');
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/google-chrome',
    headless: 'new',
    args: ['--no-sandbox', '--disable-gpu'],
    defaultViewport: { width: 1400, height: 1000 }
  });
  const page = await browser.newPage();
  page.on('pageerror', e => console.log('PAGEERROR:', e.message));
  await page.goto('file:///tmp/discbuild/index.html', { waitUntil: 'load' });
  await page.click('[data-disc-open]');
  await sleep(300);

  // слушатели-отладчики
  await page.evaluate(() => {
    window.__dbg = [];
    const ul = document.querySelector('.disc-list');
    ['pointerdown','pointermove','pointerup','pointerover'].forEach(t => {
      ul.addEventListener(t, e => {
        if (t !== 'pointermove' || window.__dbg.length < 40) window.__dbg.push(t + ':' + e.pointerType + ':' + e.pointerId);
      });
    });
  });

  const r = await page.evaluate(() => {
    const items = document.querySelectorAll('.disc-pane.is-active .disc-item');
    const r0 = items[0].getBoundingClientRect();
    const r3 = items[3].getBoundingClientRect();
    return { fx: r0.x + r0.width/2, fy: r0.y + r0.height/2, tx: r3.x + r3.width/2, ty: r3.y + r3.height/2 };
  });
  console.log('rects:', JSON.stringify(r));
  await page.mouse.move(r.fx, r.fy); await sleep(80);
  await page.mouse.down(); await sleep(80);
  for (let s = 1; s <= 15; s++) {
    await page.mouse.move(r.fx, r.fy + (r.ty - r.fy) * s / 15, { steps: 1 });
    await sleep(25);
  }
  await page.mouse.move(r.tx, r.ty + 15, { steps: 3 }); await sleep(80);
  await page.mouse.up(); await sleep(150);

  const out = await page.evaluate(() => ({
    dbg: window.__dbg.slice(0, 12),
    order: [...document.querySelectorAll('.disc-pane.is-active .disc-list')][0]
      ? [...document.querySelectorAll('.disc-pane.is-active .disc-list')[0].querySelectorAll('.disc-item')].map(li => li.getAttribute('data-type')).join('')
      : null,
    ghost: !!document.querySelector('.disc-item__ghost'),
    dragging: document.querySelectorAll('.disc-item.is-dragging').length
  }));
  console.log(JSON.stringify(out, null, 1));
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });
EOF
