const puppeteer = require('puppeteer-core');
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/google-chrome',
    headless: 'new', args: ['--no-sandbox', '--disable-gpu'],
    defaultViewport: { width: 1400, height: 1000 }
  });
  const page = await browser.newPage();
  await page.goto('file:///tmp/discbuild/index.html', { waitUntil: 'load' });
  await page.click('[data-disc-open]');
  await sleep(200);
  const prevDisabledOnStep0 = await page.$eval('[data-disc-prev]', el => el.disabled);
  const finishHiddenOnStep0 = await page.$eval('[data-disc-finish]', el => el.hidden);
  // переход на последний шаг через таб
  await page.evaluate(() => document.querySelectorAll('[data-step-btn]')[7].click());
  await sleep(150);
  const nextHiddenOnLast = await page.$eval('[data-disc-next]', el => el.hidden);
  const finishVisibleOnLast = await page.$eval('[data-disc-finish]', el => !el.hidden);
  // Esc + scroll lock
  await page.keyboard.press('Escape'); await sleep(150);
  const scrollUnlockedAfterEsc = await page.evaluate(() => !document.documentElement.classList.contains('no-scroll'));
  console.log(JSON.stringify({ prevDisabledOnStep0, finishHiddenOnStep0, nextHiddenOnLast, finishVisibleOnLast, scrollUnlockedAfterEsc }));
  // мобильный вьюпорт: drag за handle
  await page.setViewport({ width: 390, height: 844, hasTouch: true, isMobile: true });
  await sleep(200);
  await page.click('[data-disc-open]'); await sleep(300);
  const handleMode = await page.evaluate(() => matchMedia('(pointer: coarse)').matches);
  const r = await page.evaluate(() => {
    const items = document.querySelectorAll('.disc-pane.is-active .disc-item');
    const h = items[0].querySelector('.disc-handle').getBoundingClientRect();
    const last = items[3].getBoundingClientRect();
    return { hx: h.x + h.width/2, hy: h.y + h.height/2, ty: last.y + last.height/2 };
  });
  // на тач-режиме puppeteer touchscreen не даёт pointer drag; проверим хотя бы что handle существует и touch-action none
  const touchAction = await page.evaluate(() => getComputedStyle(document.querySelector('.disc-handle')).touchAction);
  await page.screenshot({ path: 'shot-mobile.png' });
  console.log(JSON.stringify({ handleMode, touchAction }));
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });
